118	/// [`search_files`] restricted to the files `wanted` accepts, which it asks before a file is opened.
119	///
120	/// A file `wanted` rejects is never opened, counted in [`files_total`](TextSearchResult::files_total) or the ceiling,
121	/// or listed in [`unreadable`](TextSearchResult::unreadable). `wanted` sees the path joined to `root`; for a path that
122	/// is not UTF-8 it sees the path with each invalid byte sequence replaced by U+FFFD, so a rejected file is not counted
123	/// in [`non_utf8_paths`](TextSearchResult::non_utf8_paths) either. Directories are always walked. Errors are those of
124	/// [`search_files`].
125	///
126	/// # Examples
127	///
128	/// ```
129	/// use camino::Utf8Path;
130	/// use monokl::text_search::{search_files_where, TextSearchOptions};
131	///
132	/// let dir = tempfile::tempdir()?;
133	/// std::fs::write(dir.path().join("a.ts"), "alpha\n")?;
134	/// std::fs::write(dir.path().join("a.txt"), "alpha\n")?;
135	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
136	///
137	/// let result =
138	///     search_files_where(root, &["alpha"], &TextSearchOptions::default(), &|path| path.extension() == Some("ts"))?;
139	/// assert_eq!(result.hits.keys().collect::<Vec<_>>(), [&root.join("a.ts")]);
140	/// assert_eq!(result.files_total, 1);
141	/// # Ok::<(), Box<dyn std::error::Error>>(())
142	/// ```
143	pub fn search_files_where(
144	    root: &Utf8Path,
145	    patterns: &[&str],
146	    opts: &TextSearchOptions,
147	    wanted: &dyn Fn(&Utf8Path) -> bool,
148	) -> Result<TextSearchResult> {
149	    search_in_batches(root, patterns, opts, wanted, rayon::current_num_threads() * BATCH_FILES_PER_THREAD)
150	}
