152	/// [`search_files`] with the number of files searched before their outcomes are folded into the result. The result does
153	/// not depend on it; it bounds how many files' hits are held beyond the kept ones.
154	fn search_in_batches(
155	    root: &Utf8Path,
156	    patterns: &[&str],
157	    opts: &TextSearchOptions,
158	    wanted: &dyn Fn(&Utf8Path) -> bool,
159	    batch_size: usize,
160	) -> Result<TextSearchResult> {
161	    let matcher = compile(patterns)?;
162	    let root_error = |source| MonoklError::Walk { path: root.to_owned(), source };
163	    let metadata = std::fs::metadata(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
164	    if !metadata.is_dir() {
165	        return Err(root_error(ignore::Error::Io(io::Error::from(io::ErrorKind::NotADirectory))));
166	    }
167	    // Listed here as well as by the walk, so a root that cannot be listed fails even when there is nothing to search.
168	    std::fs::read_dir(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
169	    let mut result = TextSearchResult::default();
170	    let Some(matcher) = matcher else {
171	        return Ok(result);
172	    };
173	    // Passthru hands every line to the sink, so a CRLF line the matcher rejected because it saw the `\r` can still be
174	    // checked against its text without the terminator. BOM sniffing is off so a UTF-16 file's NUL bytes mark it binary
175	    // and a UTF-8 BOM stays in the first line's text instead of being decoded away.
176	    let mut searcher_builder = SearcherBuilder::new();
177	    searcher_builder.binary_detection(BinaryDetection::quit(b'\x00')).bom_sniffing(false).passthru(true);
178	    // The `ignore` crate's own parent support reads every ancestor up to `/`, so the walk covers the root and the
179	    // repository's parent files are applied by `ParentIgnores`. Global and `.git/info/exclude` rules stay off so the
180	    // same checkout gives the same result on every machine.
181	    let parents = if opts.respect_ignore_files { ParentIgnores::load(root, &mut result) } else { None };
182	    let mut builder = WalkBuilder::new(root);
183	    builder
184	        .standard_filters(opts.respect_ignore_files)
185	        .parents(false)
186	        .git_global(false)
187	        .git_exclude(false)
188	        .require_git(false)
189	        .sort_by_file_name(std::cmp::Ord::cmp);
190	    if let Some(parents) = parents {
191	        let root = root.to_owned();
192	        builder.filter_entry(move |entry| {
193	            let Some(path) = Utf8Path::from_path(entry.path()) else { return true };
194	            let Ok(relative) = path.strip_prefix(&root) else { return true };
195	            !parents.excludes(relative, entry.file_type().is_some_and(|file_type| file_type.is_dir()))
196	        });
197	    }
198	    let walk = builder.build();
199	    // Walk errors and files keep the position they had in the walk, so `unreadable` lists them in walk order.
200	    let mut items = Vec::new();
201	    for entry in walk {
202	        let entry = match entry {
203	            Ok(entry) => entry,
204	            Err(err) if err.depth() == Some(0) => return Err(root_error(err)),
205	            Err(err) => {
206	                collect_walk_error(&err, &mut items);
207	                continue;
208	            }
209	        };
210	        if let Some(err) = entry.error() {
211	            collect_walk_error(err, &mut items);
212	        }
213	        if !entry.file_type().is_some_and(|file_type| file_type.is_file()) {
214	            continue;
215	        }
216	        let path = match Utf8PathBuf::from_path_buf(entry.into_path()) {
217	            Ok(path) if wanted(&path) => path,
218	            Ok(_) => continue,
219	            Err(path) => {
220	                if wanted(Utf8Path::new(&path.to_string_lossy())) {
221	                    result.non_utf8_paths += 1;
222	                }
223	                continue;
224	            }
225	        };
226	        if !opts.allow_tests && is_test_path(path.strip_prefix(root).unwrap_or(&path)) {
227	            continue;
228	        }
229	        items.push(WalkItem::File(path));
230	    }
231	    // Files are searched on separate threads a batch at a time and folded in walk order, so the result and the ceiling
232	    // never depend on which thread finished first. A file's hits are dropped as soon as it is past the ceiling, so one
233	    // batch's hits are held beyond the kept files, however many files match.
234	    let batch_size = batch_size.max(1);
235	    let mut items = items.into_iter();
236	    loop {
237	        let batch: Vec<WalkItem> = items.by_ref().take(batch_size).collect();
238	        if batch.is_empty() {
239	            break;
240	        }
241	        let searched: Vec<Searched> = batch
242	            .into_par_iter()
243	            .map_init(
244	                || searcher_builder.build(),
245	                |searcher, item| match item {
246	                    WalkItem::File(path) => {
247	                        let outcome = search_file(searcher, &matcher, &path);
248	                        Searched::File(path, outcome)
249	                    }
250	                    WalkItem::WalkError(error) => Searched::WalkError(error),
251	                },
252	            )
253	            .collect();
254	        for item in searched {
255	            match item {
256	                Searched::WalkError(error) => error.record(&mut result),
257	                Searched::File(_, FileOutcome::Binary) => {}
258	                Searched::File(path, FileOutcome::Unreadable) => result.unreadable.push(path),
259	                Searched::File(path, FileOutcome::Lines(hits)) => {
260	                    if hits.is_empty() {
261	                        continue;
262	                    }
263	                    result.files_total += 1;
264	                    if result.hits.len() < opts.max_files {
265	                        result.hits.insert(path, hits);
266	                    } else {
267	                        result.ceiling_hit = true;
268	                    }
269	                }
270	            }
271	        }
272	    }
273	    Ok(result)
274	}
