276	/// The `.ignore` and `.gitignore` rules of the directories from a git repository's root down to the search root's
277	/// parent, applied as the `ignore` crate applies parent files: a rule nearer the entry wins, `.ignore` wins over
278	/// `.gitignore` in one directory, and rules inside the search root win over all of them.
279	struct ParentIgnores {
280	    /// The canonical search root, which the matchers' paths are built from.
281	    base: Utf8PathBuf,
282	    /// Nearest directory first.
283	    parents: Vec<DirRules>,
284	    /// Rules of the directories inside the root, read when first needed.
285	    inside: Mutex<FxHashMap<Utf8PathBuf, Arc<DirRules>>>,
286	}
287	
288	/// One directory's `.ignore` and `.gitignore` files.
289	struct DirRules {
290	    ignore: Gitignore,
291	    gitignore: Gitignore,
292	}
293	
294	impl DirRules {
295	    /// Reads the directory's rules, with the errors from files that could not be read or parsed.
296	    fn read(dir: &Utf8Path) -> (Self, Vec<ignore::Error>) {
297	        let (ignore, ignore_err) = Gitignore::new(dir.join(".ignore"));
298	        let (gitignore, gitignore_err) = Gitignore::new(dir.join(".gitignore"));
299	        (Self { ignore, gitignore }, ignore_err.into_iter().chain(gitignore_err).collect())
300	    }
301	
302	    /// Whether either file has a rule, ignoring or whitelisting, that matches. `Some(true)` is an ignore.
303	    fn verdict(&self, path: &Utf8Path, is_dir: bool) -> Option<bool> {
304	        let matched =
305	            self.ignore.matched(path, is_dir).map(|_| ()).or(self.gitignore.matched(path, is_dir).map(|_| ()));
306	        match matched {
307	            ignore::Match::None => None,
308	            ignore::Match::Ignore(()) => Some(true),
309	            ignore::Match::Whitelist(()) => Some(false),
310	        }
311	    }
312	}
313	
314	impl ParentIgnores {
315	    /// Reads the parent rules for `root`, or `None` when `root` has no `.git` ancestor, is itself the repository
316	    /// root, or no parent directory has a rule. Read errors go in `result` like walk errors do.
317	    fn load(root: &Utf8Path, result: &mut TextSearchResult) -> Option<Self> {
318	        let base = root.canonicalize_utf8().ok()?;
319	        let repo_root = base.ancestors().find(|dir| dir.join(".git").symlink_metadata().is_ok())?;
320	        let mut parents = Vec::new();
321	        for dir in base.ancestors().skip(1).take_while(|dir| dir.starts_with(repo_root)) {
322	            let (rules, errors) = DirRules::read(dir);
323	            for err in &errors {
324	                record_walk_error(err, result);
325	            }
326	            parents.push(rules);
327	        }
328	        parents.iter().any(|rules| !rules.ignore.is_empty() || !rules.gitignore.is_empty()).then(|| Self {
329	            base,
330	            parents,
331	            inside: Mutex::new(FxHashMap::default()),
332	        })
333	    }
334	
335	    /// Whether a parent rule excludes the entry at `relative` below the root, and no rule inside the root matches it.
336	    fn excludes(&self, relative: &Utf8Path, is_dir: bool) -> bool {
337	        if relative.as_str().is_empty() {
338	            return false;
339	        }
340	        let path = self.base.join(relative);
341	        let decided_inside = path
342	            .ancestors()
343	            .skip(1)
344	            .take_while(|dir| dir.starts_with(&self.base))
345	            .any(|dir| self.inside_rules(dir).verdict(&path, is_dir).is_some());
346	        if decided_inside {
347	            return false;
348	        }
349	        self.parents.iter().find_map(|rules| rules.verdict(&path, is_dir)).unwrap_or(false)
350	    }
351	
352	    fn inside_rules(&self, dir: &Utf8Path) -> Arc<DirRules> {
353	        let mut cache = self.inside.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
354	        // Read errors are dropped: the walk reads the same files and reports them.
355	        Arc::clone(cache.entry(dir.to_owned()).or_insert_with(|| Arc::new(DirRules::read(dir).0)))
356	    }
357	}
358	
359	/// Compiles each pattern alone, then all together, so an invalid one always fails the search. `None` when there are no
360	/// patterns.
361	fn compile(patterns: &[&str]) -> Result<Option<RegexMatcher>> {
362	    let mut builder = RegexMatcherBuilder::new();
363	    builder.case_insensitive(true);
364	    // `build_many` joins the patterns with `|` before parsing, so halves such as `(a` and `b)` would compile together.
365	    for pattern in patterns {
366	        builder.build(pattern)?;
367	    }
368	    if patterns.is_empty() {
369	        return Ok(None);
370	    }
371	    Ok(Some(builder.build_many(patterns)?))
372	}
373	
374	/// Lists the path a walk error names in `unreadable`, or counts it when it names none that is UTF-8.
375	fn record_walk_error(err: &ignore::Error, result: &mut TextSearchResult) {
376	    let mut items = Vec::new();
377	    collect_walk_error(err, &mut items);
378	    for item in items {
379	        match item {
380	            WalkItem::WalkError(error) => error.record(result),
381	            WalkItem::File(_) => {}
382	        }
383	    }
384	}
385	
386	/// Appends one item per path a walk error names, or per failure that names no UTF-8 path.
387	fn collect_walk_error(err: &ignore::Error, items: &mut Vec<WalkItem>) {
388	    match err {
389	        ignore::Error::Partial(errs) => {
390	            for err in errs {
391	                collect_walk_error(err, items);
392	            }
393	        }
394	        ignore::Error::WithPath { path, .. } | ignore::Error::Loop { child: path, .. } => {
395	            items.push(WalkItem::WalkError(match Utf8Path::from_path(path) {
396	                Some(path) => WalkError::Path(path.to_owned()),
397	                None => WalkError::WithoutPath,
398	            }));
399	        }
400	        ignore::Error::WithDepth { err, .. } | ignore::Error::WithLineNumber { err, .. } => {
401	            collect_walk_error(err, items);
402	        }
403	        ignore::Error::Io(_)
404	        | ignore::Error::Glob { .. }
405	        | ignore::Error::UnrecognizedFileType(_)
406	        | ignore::Error::InvalidDefinition => items.push(WalkItem::WalkError(WalkError::WithoutPath)),
407	    }
408	}
409	
410	/// What the walk produced, in the order it produced it.
411	enum WalkItem {
412	    File(Utf8PathBuf),
413	    WalkError(WalkError),
414	}
415	
416	/// One failure the walk reported.
417	enum WalkError {
418	    Path(Utf8PathBuf),
419	    WithoutPath,
420	}
421	
422	impl WalkError {
423	    /// Lists the path once, or counts a failure that names no UTF-8 path.
424	    fn record(self, result: &mut TextSearchResult) {
425	        match self {
426	            Self::Path(path) if result.unreadable.contains(&path) => {}
427	            Self::Path(path) => result.unreadable.push(path),
428	            Self::WithoutPath => result.walk_errors_without_path += 1,
429	        }
430	    }
431	}
432	
433	/// A [`WalkItem`] after its file, if any, has been searched.
434	enum Searched {
435	    File(Utf8PathBuf, FileOutcome),
436	    WalkError(WalkError),
437	}
438	
439	/// How searching one file ended.
440	enum FileOutcome {
441	    Binary,
442	    Unreadable,
443	    /// The file's matching lines, possibly none.
444	    Lines(Vec<LineHit>),
445	}
446	
447	fn search_file(searcher: &mut Searcher, matcher: &RegexMatcher, path: &Utf8Path) -> FileOutcome {
448	    let mut sink = LineCollector::new(matcher);
449	    match searcher.search_path(matcher, path.as_std_path(), &mut sink) {
450	        Err(_) => FileOutcome::Unreadable,
451	        Ok(()) if sink.binary => FileOutcome::Binary,
452	        Ok(()) => FileOutcome::Lines(sink.hits),
453	    }
454	}
455	
456	/// Collects matching lines, and stops at the first sign of binary data so the caller can discard the whole file,
457	/// including lines matched before the NUL byte was reached. A matching line that is not UTF-8 is kept with its invalid
458	/// bytes replaced by U+FFFD, and does not stop the search, so a NUL later in the file still marks it binary.
459	///
460	/// The searcher strips only the `\n` before matching, so a line ending in `\r\n` is matched again here against its
461	/// text without the terminator: a pattern always sees exactly the text a hit reports.
462	struct LineCollector<'m> {
463	    matcher: &'m RegexMatcher,
464	    /// Matches one CRLF line's text, which holds no `\n`, so it searches it as a single line.
465	    line_searcher: Searcher,
466	    /// Reused to hold the text [`Self::line_searcher`] searches.
467	    line_buf: Vec<u8>,
468	    hits: Vec<LineHit>,
469	    binary: bool,
470	}
471	
472	impl<'m> LineCollector<'m> {
473	    fn new(matcher: &'m RegexMatcher) -> Self {
474	        Self {
475	            matcher,
476	            line_searcher: SearcherBuilder::new().bom_sniffing(false).build(),
477	            line_buf: Vec::new(),
478	            hits: Vec::new(),
479	            binary: false,
480	        }
481	    }
482	
483	    /// Records `line` as a hit when it matches. `searcher_matched` is the searcher's verdict, which is final unless the
484	    /// line ends in `\r\n`.
485	    fn line(&mut self, line_number: Option<u64>, line: &[u8], searcher_matched: bool) -> io::Result<()> {
486	        let text = without_line_terminator(line);
487	        let matched = if line.ends_with(b"\r\n") { self.text_matches(text)? } else { searcher_matched };
488	        if !matched {
489	            return Ok(());
490	        }
491	        let line_number = line_number
492	            .and_then(|line_number| usize::try_from(line_number).ok())
493	            .ok_or_else(|| io::Error::other("matched line has no usable line number"))?;
494	        self.hits.push(LineHit { line_number, text: String::from_utf8_lossy(text).into_owned() });
495	        Ok(())
496	    }
497	
498	    fn text_matches(&mut self, text: &[u8]) -> io::Result<bool> {
499	        // An empty slice has no lines to match, so the text is searched as one `\n`-terminated line, which the
500	        // searcher strips again before matching.
501	        self.line_buf.clear();
502	        self.line_buf.extend_from_slice(text);
503	        self.line_buf.push(b'\n');
504	        let mut found = AnyMatch(false);
505	        self.line_searcher.search_slice(self.matcher, &self.line_buf, &mut found)?;
506	        Ok(found.0)
507	    }
508	}
509	
510	impl Sink for LineCollector<'_> {
511	    type Error = io::Error;
512	
513	    fn matched(&mut self, _searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
514	        self.line(mat.line_number(), mat.bytes(), true)?;
515	        Ok(true)
516	    }
517	
518	    fn context(&mut self, _searcher: &Searcher, context: &SinkContext<'_>) -> io::Result<bool> {
519	        self.line(context.line_number(), context.bytes(), false)?;
520	        Ok(true)
521	    }
522	
523	    fn binary_data(&mut self, _searcher: &Searcher, _binary_byte_offset: u64) -> io::Result<bool> {
524	        self.binary = true;
525	        Ok(false)
526	    }
527	}
