529	/// Records whether a search found any match, stopping at the first.
530	struct AnyMatch(bool);
531	
532	impl Sink for AnyMatch {
533	    type Error = io::Error;
534	
535	    fn matched(&mut self, _searcher: &Searcher, _mat: &SinkMatch<'_>) -> io::Result<bool> {
536	        self.0 = true;
537	        Ok(false)
538	    }
539	}
