541	/// Strips one trailing `\n` or `\r\n`. A `\r` not followed by `\n` is line content and stays.
542	fn without_line_terminator(line: &[u8]) -> &[u8] {
543	    match line.strip_suffix(b"\n") {
544	        Some(line) => line.strip_suffix(b"\r").unwrap_or(line),
545	        None => line,
546	    }
547	}
