549	/// Classifies a path relative to the search root, so directories above the root never make a file a test.
550	fn is_test_path(relative: &Utf8Path) -> bool {
551	    let path: String = relative.components().flat_map(|component| ["/", component.as_str()]).collect();
552	    path.contains("/__tests__/")
553	        || path.contains("/test/")
554	        || path.contains("/tests/")
555	        || path.contains("/spec/")
556	        || path.ends_with(".test.ts")
557	        || path.ends_with(".test.tsx")
558	        || path.ends_with(".test.js")
559	        || path.ends_with(".test.jsx")
560	        || path.ends_with(".test.mjs")
561	        || path.ends_with(".test.cjs")
562	        || path.ends_with(".test.mts")
563	        || path.ends_with(".test.cts")
564	        || path.ends_with(".spec.ts")
565	        || path.ends_with(".spec.tsx")
566	        || path.ends_with(".spec.js")
567	        || path.ends_with(".spec.jsx")
568	        || path.ends_with(".spec.mjs")
569	        || path.ends_with(".spec.cjs")
570	        || path.ends_with(".spec.mts")
571	        || path.ends_with(".spec.cts")
572	        // The out-of-line `#[cfg(test)] mod tests;` of Rust: the attribute is in the parent file, so the file itself
573	        // can only be recognized by its name.
574	        || path.ends_with("/tests.rs")
575	        || path.ends_with("/test.rs")
576	        || path.ends_with("_tests.rs")
577	        || path.ends_with("_test.rs")
578	}
