67	/// Runs a search over `request.root` and returns ranked blocks.
68	///
69	/// Text search finds the lines matching the query's positive terms; files with a line matching an excluded term, or
70	/// lacking a match for a required term, drop out. Each remaining file goes to the analyzer that owns it, and only
71	/// blocks containing a matching line are kept, ranked with BM25 and deduplicated. A matching line belongs to the
72	/// smallest block containing it, so a class or object literal keeps only the matches outside its members and is
73	/// dropped when it has none. Files no analyzer supports, or that `language` excludes, are never opened, counted or reported.
74	///
75	/// BM25 query terms are the lowercase [`tokenize`] output of each non-excluded literal term. Regex terms select
76	/// lines and appear in `matched_keywords` but add no BM25 terms. A query with only excluded terms has nothing to
77	/// search for and returns an empty result with one `Skipped` diagnostic.
78	///
79	/// # Errors
80	///
81	/// - [`MonoklError::TooManyTerms`] if the query has too many terms.
82	/// - [`MonoklError::RegexBuild`] if any term is not a valid regex; no file is read first.
83	/// - [`MonoklError::Io`] or [`MonoklError::NonUtf8Path`] if `request.root` cannot be canonicalized.
84	/// - [`MonoklError::Walk`] if the root is not a listable directory.
85	///
86	/// # Examples
87	///
88	/// ```
89	/// use camino::Utf8Path;
90	/// use monokl::analysis::registry::AnalyzerRegistry;
91	/// use monokl::pipeline::{SearchRequest, search};
92	///
93	/// let dir = tempfile::tempdir()?;
94	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
95	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
96	/// let request = SearchRequest {
97	///     root,
98	///     query: "alpha",
99	///     exact: false,
100	///     allow_tests: false,
101	///     respect_ignore_files: true,
102	///     language: None,
103	/// };
104	///
105	/// // With no analyzer registered, no file is owned, so none is searched.
106	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
107	/// assert_eq!(result.files_total, 0);
108	/// assert!(result.ranked.is_empty());
109	/// # Ok::<(), Box<dyn std::error::Error>>(())
110	/// ```
111	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
112	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
113	}
114	
115	/// A block annotated with its matches, and its tokens.
116	type Candidate = (CodeBlock, Vec<String>);
117	
118	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
119	fn search_with_ceiling(
120	    registry: &AnalyzerRegistry,
121	    request: &SearchRequest<'_>,
122	    max_files: usize,
123	) -> Result<SearchResult> {
124	    let SearchRequest { root, query, exact, allow_tests, respect_ignore_files, language } = *request;
125	    if let Some(language) = language {
126	        match analyzer_language(language) {
127	            None => {
128	                return Ok(SearchResult::skipped(format!(
129	                    "language {language:?} not supported in v1; only TypeScript, JavaScript and Rust"
130	                )));
131	            }
132	            Some(id) if !registry.handles(id) => {
133	                return Ok(SearchResult::skipped(format!("language {language:?} has no analyzer in this build")));
134	            }
135	            Some(_) => {}
136	        }
137	    }
138	
139	    let terms = if exact {
140	        if query.trim().is_empty() {
141	            Vec::new()
142	        } else {
143	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
144	        }
145	    } else {
146	        parse(query)?
147	    };
148	    let plan = QueryPlan::from_terms(terms);
149	    let patterns = plan.search_patterns();
150	    if patterns.is_empty() {
151	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
152	    }
153	
154	    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
155	    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
156	    let root = canonicalize(root)?;
157	
158	    // A file no analyzer would read, or that `language` excludes, is never opened: it could not yield a block, and
159	    // counting it would let it use up the file ceiling.
160	    let wanted = |path: &Utf8Path| searchable(registry, language, path);
161	    let found = search_files_where(
162	        &root,
163	        &patterns,
164	        &TextSearchOptions { allow_tests, respect_ignore_files, max_files },
165	        &wanted,
166	    )?;
167	    let mut diagnostics = text_search_diagnostics(&found);
168	
169	    // The ceiling must not apply here: an excluded file past it would wrongly survive.
170	    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
171	        BTreeSet::new()
172	    } else {
173	        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
174	        let excluded = search_files_where(
175	            &root,
176	            &excluded_patterns,
177	            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
178	            &wanted,
179	        )?;
180	        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
181	        for path in &excluded.unreadable {
182	            if !found.unreadable.contains(path) {
183	                diagnostics.push(unreadable_diagnostic(path));
184	            }
185	        }
186	        excluded.hits.into_keys().collect()
187	    };
188	
189	    let survivors: Vec<(&Utf8PathBuf, &Vec<LineHit>)> = found
190	        .hits
191	        .iter()
192	        .filter(|(path, _)| !excluded_files.contains(*path))
193	        .filter(|(_, hits)| plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text))))
194	        .collect();
195	    // Files are analyzed on separate threads, but each result is kept in path order, so the output never depends on
196	    // which thread finished first.
197	    let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language, allow_tests };
198	    let per_file: Vec<(Vec<Candidate>, Vec<Diagnostic>)> = survivors
199	        .into_par_iter()
200	        .map(|(path, hits)| {
201	            let (mut blocks, mut file_diagnostics) = (Vec::new(), Vec::new());
202	            retrieve_blocks(&ctx, path, hits, &read_source, &mut blocks, &mut file_diagnostics);
203	            (blocks, file_diagnostics)
204	        })
205	        .collect();
206	    let mut candidates: Vec<Candidate> = Vec::new();
207	    for (blocks, file_diagnostics) in per_file {
208	        candidates.extend(blocks);
209	        diagnostics.extend(file_diagnostics);
210	    }
211	
212	    let bm25_terms = bm25_terms(&plan);
213	    let df = document_frequencies(&candidates, &bm25_terms);
214	    let bm25_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
215	    let ranked = dedup_blocks(rank_blocks(candidates, &bm25_terms, &df));
216	
217	    Ok(SearchResult { ranked, files_total: found.files_total, ceiling_hit: found.ceiling_hit, diagnostics })
218	}
