220	/// The analyzer language that serves `language` in v1, or `None` when no analyzer path exists for it.
221	fn analyzer_language(language: Language) -> Option<LanguageId> {
222	    match language {
223	        Language::TypeScript | Language::JavaScript => Some(LanguageId::TypeScript),
224	        Language::Rust => Some(LanguageId::Rust),
225	        Language::Python => None,
226	    }
227	}
