229	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
230	fn compile(pattern: &str) -> Result<RegexMatcher> {
231	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
232	}
233	
234	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
235	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
236	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
237	}
