239	/// A file's text, and whether getting it meant replacing bytes that are not UTF-8.
240	struct Source {
241	    text: String,
242	    lossy: bool,
243	}
244	
245	/// Reads `path`, replacing each invalid UTF-8 sequence with U+FFFD so the file is still searched and extracted.
246	fn read_source(path: &Utf8Path) -> io::Result<Source> {
247	    let bytes = std::fs::read(path)?;
248	    Ok(match String::from_utf8(bytes) {
249	        Ok(text) => Source { text, lossy: false },
250	        Err(err) => Source { text: String::from_utf8_lossy(err.as_bytes()).into_owned(), lossy: true },
251	    })
252	}
253	
254	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
255	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
256	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
257	}
258	
259	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
260	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
261	}
262	
263	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
264	    skipped(Some(path), "file could not be read")
265	}
