267	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
268	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
269	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
270	    if found.non_utf8_paths > 0 {
271	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
272	    }
273	    if found.walk_errors_without_path > 0 {
274	        diagnostics.push(skipped(
275	            None,
276	            format!("{} directory walk errors did not name a UTF-8 path", found.walk_errors_without_path),
277	        ));
278	    }
279	    diagnostics
280	}
