fn cut_at_char_boundary(text: &[u8], max: usize) -> &[u8] {
    if text.len() <= max {
        return text;
    }
    let mut end = max;
    // A continuation byte is `10xxxxxx`; the cut goes before the lead byte of the character it would split.
    while end > 0 && text.get(end).is_some_and(|byte| byte & 0xC0 == 0x80) {
